CREATE TEMP TABLE merge_target (id integer PRIMARY KEY, label text NOT NULL);
INSERT INTO merge_target VALUES (1, 'old');
MERGE INTO merge_target AS target USING (VALUES (1, 'updated'), (2, 'new')) AS source(id, label) ON target.id = source.id
WHEN MATCHED THEN UPDATE SET label = source.label
WHEN NOT MATCHED THEN INSERT (id, label) VALUES (source.id, source.label);
SELECT * FROM merge_target ORDER BY id;
